{"implementation": "def solve(case):
    segments = case.get("segments", [])
    budget = int(case.get("budget", 0))

    n = len(segments)
    allocations = [0] * n

    # First satisfy minimums in input order as far as the budget allows.
    remaining = budget
    for i, seg in enumerate(segments):
        minimum = int(seg.get("minimum", 0))
        capacity = int(seg.get("capacity", minimum))
        base = minimum if minimum <= capacity else capacity
        give = base if remaining >= base else remaining
        allocations[i] = give
        remaining -= give
        if remaining <= 0:
            remaining = 0
            break

    # Spend any remaining budget where it has the highest marginal value.
    order = sorted(
        range(n),
        key=lambda i: (-int(segments[i].get("importance", 0)), i),
    )
    while remaining > 0:
        changed = False
        for i in order:
            capacity = int(segments[i].get("capacity", allocations[i]))
            if allocations[i] < capacity:
                add = capacity - allocations[i]
                if add > remaining:
                    add = remaining
                allocations[i] += add
                remaining -= add
                changed = True
                if remaining <= 0:
                    break
        if not changed:
            break

    by_name = {}
    for seg, amount in zip(segments, allocations):
        by_name[seg.get("name")] = int(amount)

    return {
        "allocations": [int(x) for x in allocations],
        "by_name": by_name,
        "total": int(sum(allocations)),
    }
"}
